questionvariables.text:
/* Design: step dropdown plus the correct value. Seven steps; Step 1 is a height-and-domain step, so the correct step is never Step 1. er 1: step 2 uses base s - x, and steps 3 to 7 follow from it; er 2: step 6 calls x = s/6 the least volume and uses x = s/2; er 3: step 7 uses s - s/6 for the base. Source: original. */
L: [[24,1],[30,2],[36,3],[18,1],[42,2],[48,3],[60,1],[54,2],[12,3],[66,1]];
ix: 1+rand(10);
s0: L[ix][1]; er: L[ix][2];
corr: 2*s0^3/27;
shown: if er=1 then 4*s0^3/27 elseif er=2 then 0 else 25*s0^3/216;
opts: [["s1",false,"Step 1"],["s2",is(er=1),"Step 2"],["s3",false,"Step 3"],["s4",false,"Step 4"],["s5",false,"Step 5"],["s6",is(er=2),"Step 6"],["s7",is(er=3),"Step 7"]];
